/**
 * Coarse outlines of the countries and states in `trail-regions.ts`, and of
 * the unlisted countries bordering them (`other`), for `region-detect.ts`.
 * Generated by `scripts/build-region-shapes.ts` from Natural Earth 1:50m
 * (public domain); do not edit by hand.
 *
 * Each ring is a flat `[lon, lat, dLon, dLat, …]` list in thousandths of a
 * degree: the first vertex, then each one as its step from the one before.
 * Rings close implicitly. A shape's rings are tested even-odd, so holes
 * (Lesotho in South Africa) need no marking.
 */

export interface RegionShape {
  /** ISO 3166-1 alpha-2. */
  country: string;
  /** A state code from `trail-regions.ts`, or null for the whole country. */
  state: string | null;
  /** A country `trail-regions.ts` does not list, kept so a route inside it is not taken for its neighbour. */
  other?: true;
  rings: readonly (readonly number[])[];
}

